#1. Project Overview
-------------------
This project converts a large Excel dataset containing smartphone
specifications into a fully structured SQL Server database.
The goal is to clean, organize, validate, and store the data
in a relational format suitable for analysis and portfolio use.

#2. Data Preparation (Excel)
---------------------------
- Reviewed the Excel file for missing values.
- Ensured phone_id values were unique.
- Standardized column names.
- Exported the cleaned file as CSV for SQL import.

#3. Database Design
------------------
- Created a table named PhonesFullData.
- Selected appropriate data types (INT, VARCHAR, FLOAT).
- Defined phone_id as PRIMARY KEY.
- Ensured all fields match the structure of the Excel dataset.

#4. Table Creation (SQL)
-----------------------
The following SQL code was used to create the table:
*/

USE model;

CREATE TABLE PhonesFullData (
    phone_id INT PRIMARY KEY,
    brand VARCHAR(50),
    model VARCHAR(100),
    marketing_name VARCHAR(100),
    release_year INT,
    release_month INT,
    operating_system VARCHAR(50),
    os_version BIT,
    is_5g_supported BIT,
    screen_size_inches DECIMAL(6,1),
    screen_resolution VARCHAR(30),
    refresh_rate_hz INT,
    panel_type VARCHAR(50),
    processor_brand VARCHAR(50),
    processor_model VARCHAR(50),
    core_count INT,
    ram_gb INT,
    storage_gb INT,
    card_slot_available BIT,
    main_camera_mp INT,
    num_rear_cameras INT,
    front_camera_mp INT,
    battery_capacity_mah INT,
    charging_speed_w INT,
    wireless_charging BIT,
    weight_grams INT,
    thickness_mm DECIMAL(4,1),
    body_material VARCHAR(50),
    water_resistance_rating VARCHAR(10),
    original_price_usd DECIMAL(10,2),
    region_market VARCHAR(50),
    stock_availability INT,
    user_rating DECIMAL(3,1),
    review_count INT,
    discounted_price_usd DECIMAL(10,2));




INSERT INTO PhonesFullData (
    phone_id,
    brand,
    model,
    marketing_name,
    release_year,
    release_month,
    operating_system,
    os_version,
    is_5g_supported,
    screen_size_inches,
    screen_resolution,
    refresh_rate_hz,
    panel_type,
    processor_brand,
    processor_model,
    core_count,
    ram_gb,
    storage_gb,
    card_slot_available,
    main_camera_mp,
    num_rear_cameras,
    front_camera_mp,
    battery_capacity_mah,
    charging_speed_w,
    wireless_charging,
    weight_grams,
    thickness_mm,
    body_material,
    water_resistance_rating,
    original_price_usd,
    region_market,
    stock_availability,
    user_rating,
    review_count,
    discounted_price_usd)

